  bri: 'https://md-bund.de/fileadmin/dokumente/Publikationen/SPV/Begutachtungsgrundlagen/261016_MDB_48_002_RICHTLINIE_PFLEGE_2026_16.pdf',
  bmg: 'https://www.bundesgesundheitsministerium.de/themen/pflege/online-ratgeber-pflege/pflegebeduerftig-was-nun',
