const source = (url, label) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${label}<span class="sr-only"> (öffnet in einem neuen Tab)</span></a>`;
const header = (eyebrow, title, lead) => `<header class="page-header"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${lead}</p></header>`;
const disclosure = (title, body) => `<details><summary>${title}</summary><div class="prose">${body}</div></details>`;

export const applicationTemplate = `An meine Pflegekasse / private Pflegepflichtversicherung

Betreff: Antrag auf Leistungen der Pflegeversicherung

Sehr geehrte Damen und Herren,

hiermit beantrage ich Leistungen der Pflegeversicherung und die Feststellung meines Pflegegrades. Wegen gesundheitlicher Einschränkungen benötige ich Unterstützung im Alltag.

Bitte bestätigen Sie mir den Eingang dieses Antrags mit dem Eingangsdatum, senden Sie mir die erforderlichen Unterlagen und veranlassen Sie die Begutachtung. Bitte informieren Sie mich auch über eine Pflegeberatung.

Name: [Vorname, Nachname]
Anschrift: [Straße, Hausnummer, PLZ, Ort]
Versichertennummer: [Nummer]
Datum: [Datum]
Unterschrift: [bei schriftlicher Antragstellung]

Mit freundlichen Grüßen
[Name]`;

export function guidePage() {
  return `${header('Der Weg zum Pflegegrad', 'Gut vorbereitet.<br>Schritt für Schritt.', 'Ein Antrag muss nicht kompliziert sein. Hier erfahren Sie, an wen Sie sich wenden, was Sie vorbereiten und wie es danach weitergeht.')}
  <div class="content-grid">
    <aside class="note"><p class="eyebrow">In diesem Ratgeber</p><nav aria-label="Ratgeber-Inhalt"><ol><li><a href="#guide-check">Voraussetzungen prüfen</a></li><li><a href="#guide-apply">Antrag stellen</a></li><li><a href="#guide-prepare">Begutachtung vorbereiten</a></li><li><a href="#guide-decision">Bescheid verstehen</a></li><li><a href="#guide-objection">Entscheidung überprüfen</a></li></ol></nav><p>Recherchestand: 11. November 2026.<br>Allgemeine Information, keine individuelle Rechtsberatung.</p></aside>
    <div class="steps">
      <section class="step prose" id="guide-check"><p class="eyebrow">01 / Voraussetzungen</p><h2>Wann ist ein Antrag sinnvoll?</h2>
      <p>Wenn die Person wegen gesundheitlicher Einschränkungen regelmäßig Hilfe von anderen Menschen braucht, kann ein Pflegegrad infrage kommen. Dabei zählen körperliche, geistige und psychische Einschränkungen. Entscheidend ist, was im Alltag selbstständig gelingt.</p>
      <p>Die Einschränkungen müssen voraussichtlich mindestens sechs Monate bestehen. <strong>Sie müssen mit dem Antrag keine sechs Monate warten.</strong> Es geht um die erwartete Dauer. Eine Diagnose allein bestimmt noch keinen Pflegegrad. ${source(links.sgb14, '§ 14 SGB XI')}</p>
      <p>Für Leistungen der sozialen Pflegeversicherung sind grundsätzlich zwei Versicherungsjahre innerhalb der letzten zehn Jahre erforderlich. Der Selbstcheck prüft diese Versicherungszeiten nicht. ${source('https://www.gesetze-im-internet.de/sgb_11/__33.html', '§ 33 SGB XI')}</p>
      <a class="text-link" href="#/rechner">Den eigenen Unterstützungsbedarf einschätzen →</a></section>

      <section class="step prose" id="guide-apply"><p class="eyebrow">02 / Antrag</p><h2>Ein kurzer Antrag genügt für den Anfang.</h2>
      <p>Bei gesetzlicher Versicherung ist die <strong>Pflegekasse bei Ihrer Krankenkasse</strong> zuständig. Privat Versicherte wenden sich an ihre private Pflegepflichtversicherung. Der Antrag kann zunächst formlos gestellt werden: schriftlich, telefonisch oder über ein angebotenes Onlineverfahren.</p>
      <p>Auch Angehörige oder andere Vertrauenspersonen können den Antrag mit entsprechender Vollmacht stellen. Anschließend kann die Versicherung ein Formular und weitere Unterlagen anfordern. ${source(links.bmg, 'BMG: Antragstellung')}</p>
      <h3>Das Eingangsdatum zählt.</h3><p>Lassen Sie sich den Eingang bestätigen. Bewahren Sie Schreiben und Portalbestätigungen auf; notieren Sie bei einem Telefonat Datum und Ansprechpartner. Leistungen beginnen grundsätzlich mit der Antragstellung, frühestens bei erfüllten Voraussetzungen. Wird erst in einem späteren Monat als dem Eintritt der Pflegebedürftigkeit beantragt, gilt der Beginn des Antragsmonats. ${source('https://www.gesetze-im-internet.de/sgb_11/__33.html', '§ 33 Abs. 1 SGB XI')}</p>
      <details><summary>Muster für einen formlosen Antrag</summary><p>Dieses Muster können Sie kopieren und anschließend außerhalb dieser Website ergänzen. Es wird hier nicht versendet. Bei Vertretung bitte die Vollmacht beifügen.</p><label for="application-template">Antragstext zum Kopieren</label><textarea id="application-template" readonly rows="17">${applicationTemplate}</textarea><button class="button secondary" data-action="copy-application">Muster kopieren</button><p id="copy-status" role="status" aria-live="polite"></p></details>
      <h3>Beratung gehört dazu.</h3><p>Die Pflegekasse muss unmittelbar einen Beratungstermin oder einen Beratungsgutschein anbieten. Grundsätzlich soll die Beratung innerhalb von zwei Wochen nach Antragseingang stattfinden; auf Ihren Wunsch auch später. Fragen Sie nach Pflegeberatung oder einem Pflegestützpunkt. ${source('https://www.gesetze-im-internet.de/sgb_11/__7b.html', '§ 7b SGB XI')}</p></section>

      <section class="step prose" id="guide-prepare"><p class="eyebrow">03 / Begutachtung</p><h2>Zeigen Sie Ihren wirklichen Alltag.</h2>
      <p>Die Pflegekasse beauftragt in der Regel den Medizinischen Dienst. Bei privater Pflegepflichtversicherung übernimmt Medicproof die Begutachtung. Die gutachtende Person bespricht die Selbstständigkeit in sechs Lebensbereichen und prüft vorhandene Unterlagen. Die Begutachtung erfolgt grundsätzlich im Wohnbereich; unter bestimmten Voraussetzungen sind andere Verfahren möglich. ${source(links.md, 'Medizinischer Dienst')} · ${source(links.medicproof, 'Medicproof')}</p>
      <h3>Das hilft beim Termin</h3><ul><li>Eine vertraute Person hinzuziehen, die den täglichen Hilfebedarf kennt. Die betroffene Person muss damit einverstanden sein.</li><li>Vorhandene Arzt- und Klinikberichte sowie den aktuellen Medikamentenplan bereitlegen.</li><li>Hilfsmittel, regelmäßige Therapien und gegebenenfalls die Pflegedokumentation zusammentragen.</li><li>Aufschreiben, welche Hilfe nötig ist: Anleitung, Erinnerung, Beaufsichtigung oder körperliche Unterstützung.</li></ul>
      <p>Fehlende Arztberichte müssen Sie laut MD-Checkliste nicht eigens neu anfordern. ${source('https://www.medizinischerdienst.de/fileadmin/MD-zentraler-Ordner/Downloads/01_Pflegebegutachtung/240322_Checkliste_zur_Pflegebegutachtung_barrierfrei.pdf', 'Offizielle Vorbereitungsliste')}</p>
      <h3>Ein Pflegetagebuch schafft Klarheit.</h3><p>Notieren Sie über mehrere Tage typische Situationen: Was gelingt selbstständig, was nur mit Hilfe und wie häufig? Halten Sie auch Schwankungen zwischen guten und schlechten Tagen fest. Das hilft, beim Gespräch nichts zu vergessen. Schildern Sie den Alltag realistisch, ohne Einschränkungen zu verharmlosen oder zu übertreiben. Pflegeminuten werden dabei nicht einfach in Pflegegradpunkte umgerechnet. ${source('https://gesund.bund.de/pflegebegutachtung', 'Vorbereitung und Pflegetagebuch')}</p></section>

      <section class="step prose" id="guide-decision"><p class="eyebrow">04 / Ergebnis</p><h2>Gutachten und Bescheid verstehen.</h2>
      <p>Die gutachtende Person vergibt Einzelpunkte. Diese werden nach festen Tabellen in gewichtete Modulpunkte umgerechnet. Es gibt 6 verschiedene Module, in welchen Punkte vergeben werden. Die Summe ergibt die Grundlage für den Pflegegrad. <a href="#/reform">So funktioniert die Berechnung →</a></p>
      <p>Die gesetzliche Pflegekasse muss grundsätzlich innerhalb von 25 Arbeitstagen nach Antragseingang den Bescheid übersenden. Prüfen Sie anschließend, ob die dort beschriebenen Fähigkeiten und Hilfen Ihrem Alltag entsprechen.</p>
      </section>

      <section class="step prose" id="guide-objection"><p class="eyebrow">05 / Nächste Schritte</p><h2>Wenn Sie mit der Entscheidung nicht einverstanden sind.</h2>
      <h3>Gesetzliche Pflegeversicherung: Widerspruch</h3><p>Bei einem ablehnenden Bescheid oder einem aus Ihrer Sicht zu niedrigen Pflegegrad können Sie grundsätzlich innerhalb <strong>eines Monats ab Bekanntgabe</strong> Widerspruch einlegen. Maßgeblich ist nicht einfach das Datum auf dem Brief. Beachten Sie die Rechtsbehelfsbelehrung. Bei Bekanntgabe im Ausland beträgt die Frist drei Monate. ${source('https://www.gesetze-im-internet.de/sgg/__84.html', '§ 84 SGG')}</p>
      <p>Ein kurzer fristwahrender Widerspruch kann zunächst genügen; die Begründung lässt sich nachreichen. Benennen Sie später anhand des Gutachtens konkrete fehlende oder unzutreffend bewertete Hilfen. Sichern Sie einen Nachweis über den rechtzeitigen Eingang.</p>
      <div class="note"><p>„Hiermit lege ich gegen Ihren Bescheid vom [Datum], mir bekannt gegeben am [Datum], Widerspruch ein. Bitte übersenden Sie mir das vollständige Pflegegutachten, falls es mir noch nicht vorliegt. Meine Begründung reiche ich nach.“</p></div>
      <p>Nutzen Sie einen unterschriebenen Brief, die Niederschrift bei der Pflegekasse oder eine gesetzlich zugelassene elektronische Form. Eine gewöhnliche E-Mail ist kein verlässlicher Ersatz. Bei fehlender oder fehlerhafter Rechtsbehelfsbelehrung gilt regelmäßig eine Jahresfrist; es gibt gesetzliche Ausnahmen. ${source('https://www.gesetze-im-internet.de/sgg/__66.html', '§ 66 SGG')}</p>
      <p>Nach einem ablehnenden Widerspruchsbescheid ist grundsätzlich innerhalb eines Monats ab Bekanntgabe Klage beim Sozialgericht möglich. Holen Sie bei Fristfragen frühzeitig fachlichen Rat ein. ${source('https://www.gesetze-im-internet.de/sgg/__87.html', '§ 87 SGG')}</p>
      <h3>Private Pflegepflichtversicherung: Überprüfung verlangen</h3><p>Hier gilt nicht das Widerspruchsverfahren der gesetzlichen Pflegekasse. Tragen Sie Ihre Einwände zeitnah schriftlich bei Ihrem Versicherer vor. Eine erneute Prüfung und ein Medicproof-Zweitgutachten kommen infrage. Für Streitigkeiten aus der privaten Pflegepflichtversicherung ist das Sozialgericht zuständig. Übertragen Sie die gesetzliche Monatsfrist nicht pauschal auf dieses Verfahren. ${source(links.medicproof, 'Medicproof: Zweitgutachten')}</p>
      <h3>Wenn sich der Hilfebedarf verändert</h3><p>Bei dauerhaft zunehmenden Einschränkungen können Sie einen höheren Pflegegrad beantragen. Nach einer Ablehnung ist auch ein neuer Antrag möglich. Ein neuer Antrag ersetzt jedoch nicht den rechtzeitigen Widerspruch gegen einen aus Ihrer Sicht fehlerhaften früheren Bescheid.</p>
      <a class="button primary" href="#/rechner">Pflegegrad jetzt einschätzen <span aria-hidden="true">↗</span></a></section>
    </div>
  </div>`;
}

export function faqPage() {
  const items = [
    ['Was ist ein Pflegegrad?', '<p>Ein Pflegegrad beschreibt, wie stark die Selbstständigkeit oder bestimmte Fähigkeiten durch gesundheitliche Einschränkungen beeinträchtigt sind. Es gibt fünf Pflegegrade. Höhere Punkte stehen für stärkere Beeinträchtigungen. Das Alter oder eine Diagnose allein bestimmen den Pflegegrad nicht.</p>'],
    ['Muss ich schon sechs Monate Hilfe benötigen?', `<p>Nein. Die Einschränkungen müssen voraussichtlich mindestens sechs Monate bestehen. Das ist eine Einschätzung der erwarteten Dauer. Ein Antrag kann schon vorher sinnvoll sein. ${source(links.sgb14, '§ 14 SGB XI')}</p>`],
    ['Wie lange dauert der Selbstcheck?', '<p>Planen Sie etwa 20 bis 30 Minuten ein; mit Unterstützungsbedarf kann es länger dauern. Sie gehen alle sechs Module durch. Antworten lassen sich jederzeit innerhalb des offenen Checks ändern. Beim Neuladen oder Schließen der Seite geht der aktuelle Stand verloren.</p>'],
    ['Ist der Rechner kostenlos und ohne Anmeldung?', '<p>Ja. Für den Selbstcheck benötigen Sie weder ein Konto noch Namen, E-Mail-Adresse oder Telefonnummer. Auch das vollständige Ergebnis ist ohne Kontaktaufnahme zugänglich.</p>'],
    ['Erhalte ich damit einen anerkannten Pflegegrad?', '<p>Nein. Das Ergebnis ist eine unverbindliche Selbsteinschätzung. Die zuständige Pflegeversicherung entscheidet auf Grundlage der fachlichen Begutachtung. Die Einschätzung einzelner Kriterien kann dabei anders ausfallen.</p>'],
    ['Kann ich den Check für einen Angehörigen ausfüllen?', '<p>Ja. Beantworten Sie die Fragen aus Sicht der betroffenen erwachsenen Person. Besprechen Sie die Angaben möglichst gemeinsam und berücksichtigen Sie den üblichen Alltag. Bei Angaben für andere Personen achten Sie auf deren Einverständnis und Privatsphäre.</p>'],
    ['Was bedeutet „selbstständig“ mit einem Hilfsmittel?', '<p>Wer eine Tätigkeit mit einem Hilfsmittel ohne Hilfe einer anderen Person ausführen kann, kann weiterhin selbstständig sein. Ein Rollator führt zum Beispiel nicht automatisch zu Punkten. Entscheidend ist die benötigte personelle Unterstützung.</p>'],
    ['Was mache ich bei einer unsicheren Antwort?', '<p>Wählen Sie „Ich bin mir nicht sicher“. Der Rechner zeigt offene Angaben und einen möglichen Punktebereich. Dieser Bereich ergibt sich aus den kleinsten und größten zulässigen Bewertungen der offenen Angaben. Er ist keine Wahrscheinlichkeit und keine Prognose für den tatsächlichen Bescheid.</p>'],
    ['Warum werden Modul 2 und 3 nicht addiert?', `<p>Das Gesetz sieht einen gemeinsamen Anteil von maximal 15 Punkten vor. Zuerst werden beide Module einzeln umgerechnet. Anschließend geht ausschließlich der höhere gewichtete Modulwert in die Gesamtsumme ein. ${source(links.sgb15, '§ 15 Abs. 3 SGB XI')}</p>`],
    ['Warum zählen Haushalt und Einkaufen nicht extra?', `<p>Außerhäusliche Aktivitäten und Haushaltsführung sind für Beratung und Versorgungsplanung wichtig. Sie werden bei der Begutachtung erfasst, erhalten aber keine zusätzliche eigene Gewichtung in der offiziellen Gesamtpunktzahl. ${source('https://www.gesetze-im-internet.de/sgb_11/__18a.html', '§ 18a Abs. 3 SGB XI')}</p>`],
    ['Ist der Rechner auch für Kinder geeignet?', '<p>Nein. Diese Version berechnet ausschließlich für Personen ab 18 Jahren. Für Kinder und Jugendliche gibt es besondere Bewertungsregeln; bei kleinen Kindern wird unter anderem mit der altersüblichen Selbstständigkeit verglichen. Bitte wenden Sie sich an Ihre Pflegeversicherung oder eine spezialisierte Pflegeberatung.</p>'],
    ['Ist Pflegegrad 5 auch unter 90 Punkten möglich?', `<p>Ja, bei einer fachlich festzustellenden besonderen Bedarfskonstellation. Die Richtlinien beschreiben hierzu die Gebrauchsunfähigkeit beider Arme und beider Beine. Der Rechner kann eine solche Ausnahme nicht abschließend beurteilen und vergibt deshalb nicht automatisch Pflegegrad 5. ${source(links.sgb15, '§ 15 Abs. 4 SGB XI')}</p>`],
    ['Werden meine Gesundheitsangaben gespeichert?', '<p>Die Antworten bleiben im Arbeitsspeicher Ihres Browsers. Der Rechner sendet sie weder an einen Server noch an KI- oder Analysedienste und legt sie nicht im dauerhaften Browserspeicher ab. Beim Zurücksetzen oder Neuladen werden sie verworfen. Ein heruntergeladenes Ergebnis bleibt auf Ihrem Gerät. <a href="#/datenschutz">Datenschutzhinweise lesen →</a></p>'],
    ['Gelten schon die neuen Pflegegradgrenzen für 2027?', '<p>Nein. Nach dem recherchierten Stand vom 11. November 2026 ist das Pflegeneuordnungsgesetz noch im parlamentarischen Verfahren. Dieser Rechner verwendet ausschließlich die geltenden Regeln. <a href="#/reform">Was zur Reform belegt ist →</a></p>'],
    ['Wer steckt hinter diesem Informationsangebot?', '<p>Die Website ist als kostenloser Informationsservice von Caro Alltagsbegleitung in Tübingen vorgesehen. Caro ist weder Pflegekasse noch Medizinischer Dienst oder staatliche Behörde. In dieser privaten Vorschau sind die rechtlichen Betreiberangaben noch zu ergänzen. <a href="#/impressum">Zum Impressum →</a></p>']
  ];
  return `${header('Häufige Fragen', 'Weniger Fragezeichen.<br>Mehr Orientierung.', 'Die wichtigsten Antworten rund um Pflegegrad, Selbstcheck und die nächsten Schritte.')}<div class="faq-list">${items.map(([t,b]) => disclosure(t,b)).join('')}</div><div class="note prose"><h2>Noch nicht sicher, wo Sie anfangen sollen?</h2><p>Unser Ratgeber begleitet Sie von der ersten Einschätzung bis zum Bescheid.</p><a class="text-link" href="#/ratgeber">Zum Ratgeber →</a></div>`;
}

export function sourcesPage() {
  return `${header('Quellen & Methodik', 'Nachvollziehbar.<br>Bis zum einzelnen Punkt.', 'Der Rechner folgt festen Regeln. Hier sehen Sie, auf welchem Rechtsstand er beruht und wie aus Antworten eine Punktzahl entsteht.')}
  <div class="prose"><div class="note"><p><strong>Recherchestand: 11. November 2026.</strong> Geltendes Bewertungsmodell für Erwachsene. Geplante PNOG-Änderungen werden nicht eingerechnet. Eine spätere Änderung der Rechtslage wird durch diese statische Version nicht automatisch übernommen.</p></div>
  <h2>Die amtlichen Grundlagen</h2><div class="table-wrap"><table><caption>Quellen und geprüfter Stand</caption><thead><tr><th scope="col">Quelle</th><th scope="col">Bedeutung und Stand</th></tr></thead><tbody>
  <tr><th scope="row">${source(links.sgb14, '§ 14 SGB XI')}</th><td>Begriff der Pflegebedürftigkeit; voraussichtliche Dauer von mindestens sechs Monaten. Konsolidierte Fassung am 11.11.2026 geprüft.</td></tr>
  <tr><th scope="row">${source(links.sgb15, '§ 15 SGB XI')}</th><td>Module, Gewichtung, Gesamtpunktgrenzen, Kinder und besondere Bedarfskonstellation. Konsolidierte Fassung am 11.11.2026 geprüft.</td></tr>
  <tr><th scope="row">${source(links.a1, 'Anlage 1 zu § 15')}</th><td>Offizielle Kriterien, Antwortkategorien und Einzelpunkte. Grundlage der versionierten Regeldaten.</td></tr>
  <tr><th scope="row">${source(links.a2, 'Anlage 2 zu § 15')}</th><td>Umrechnung der Einzelpunktsummen in gewichtete Modulpunkte.</td></tr>
  <tr><th scope="row">${source(links.bri, 'Begutachtungs-Richtlinien 2026 (PDF)')}</th><td>Erlassen am 26.08.2026, vom BMG genehmigt am 28.09.2026, in Kraft seit 01.10.2026. Erwachsene: Kapitel 5, Berechnung: Abschnitt 5.10.1.</td></tr>
  <tr><th scope="row">${source(links.md, 'Medizinischer Dienst')}</th><td>Verständliche Information zum Begutachtungsverfahren; am 11.11.2026 abgerufen.</td></tr>
  <tr><th scope="row">${source(links.bmg, 'BMG: Antragstellung und Begutachtung')}</th><td>Antrag, Zuständigkeit und Beratung; am 11.11.2026 abgerufen. Fristen zusätzlich anhand der Gesetze geprüft.</td></tr>
  </tbody></table></div>
  <p>Die ${source('https://www.gesetze-im-internet.de/sgb_11/BJNR101500994.html', 'Gesamtausgabe des SGB XI')} nennt als letzten Änderungsstand Art. 2c des Gesetzes vom 24.07.2026 (BGBl. 2026 I Nr. 228); die Bekanntmachung vom 16.09.2026 (BGBl. 2026 I Nr. 282) ist berücksichtigt. Diese Angabe betrifft das gesamte Gesetz. Sie bedeutet nicht, dass alle Berechnungsregeln an diesem Datum geändert wurden.</p>
  <p>Die Richtlinienfassung vom Oktober 2026 enthält unter anderem Änderungen zur Begutachtung von Kindern und Jugendlichen, zu Verzögerungsgründen sowie zu digitalen Prozessen. Die Berechnung dieser Website bleibt auf Erwachsene begrenzt.</p>

  <h2>So wird gerechnet</h2><ol><li>Jede Antwort wird den für dieses Kriterium vorgesehenen Einzelpunkten zugeordnet.</li><li>Innerhalb des Moduls werden Punkte nach den jeweiligen Sonderregeln zusammengefasst. Häufigkeiten in Modul 5 werden zunächst umgerechnet.</li><li>Die Einzelpunktsumme wird anhand der amtlichen Tabelle einer von fünf gewichteten Stufen zugeordnet.</li><li>Von Modul 2 und 3 zählt nur der höhere gewichtete Wert.</li><li>Die gewichteten Werte werden addiert und mit den gesetzlichen Pflegegradgrenzen verglichen.</li></ol>
  <p><strong>Gesamt = M1 + max(M2, M3) + M4 + M5 + M6.</strong> Die Rohpunkte werden nicht einfach mit einem Prozentwert multipliziert.</p>
  <div class="table-wrap"><table><caption>Geltende Umrechnungstabelle: Rohpunkte → gewichtete Punkte</caption><thead><tr><th scope="col">Modul</th><th scope="col">Stufe 0</th><th scope="col">Stufe 1</th><th scope="col">Stufe 2</th><th scope="col">Stufe 3</th><th scope="col">Stufe 4</th></tr></thead><tbody>
  <tr><th scope="row">1 · Mobilität</th><td>0–1 → 0</td><td>2–3 → 2,5</td><td>4–5 → 5</td><td>6–9 → 7,5</td><td>10–15 → 10</td></tr>
  <tr><th scope="row">2 · Kognition</th><td>0–1 → 0</td><td>2–5 → 3,75</td><td>6–10 → 7,5</td><td>11–16 → 11,25</td><td>17–33 → 15</td></tr>
  <tr><th scope="row">3 · Verhalten</th><td>0 → 0</td><td>1–2 → 3,75</td><td>3–4 → 7,5</td><td>5–6 → 11,25</td><td>7–65 → 15</td></tr>
  <tr><th scope="row">4 · Selbstversorgung</th><td>0–2 → 0</td><td>3–7 → 10</td><td>8–18 → 20</td><td>19–36 → 30</td><td>37–54 → 40</td></tr>
  <tr><th scope="row">5 · Krankheiten & Therapien</th><td>0 → 0</td><td>1 → 5</td><td>2–3 → 10</td><td>4–5 → 15</td><td>6–15 → 20</td></tr>
  <tr><th scope="row">6 · Alltag & Kontakte</th><td>0 → 0</td><td>1–3 → 3,75</td><td>4–6 → 7,5</td><td>7–11 → 11,25</td><td>12–18 → 15</td></tr>
  </tbody></table></div><p>Quelle: ${source(links.a2, 'Anlage 2 SGB XI')}. M2 und M3 teilen sich maximal 15 gewichtete Punkte.</p>

  ${disclosure('Die Sonderregeln in Modul 4', `<p>Waschen wird mit 0/1/2/3 bewertet, Essen mit 0/3/6/9, Trinken und Toilettennutzung mit 0/2/4/6. Die anderen Selbstständigkeitskriterien verwenden grundsätzlich 0/1/2/3. Inkontinenzkriterien zählen nur bei den dafür vorgesehenen Voraussetzungen.</p><p>Bei Sonden- oder parenteraler Ernährung gelten eigene Kategorien: 0 Punkte unter anderem bei selbstständiger Versorgung oder nicht täglicher Unterstützung, 6 bei täglicher zusätzlicher Ernährung, 3 bei ausschließlicher oder nahezu ausschließlicher Ernährung. Essen und Trinken werden daneben nach den tatsächlichen Fähigkeiten bewertet. ${source(links.a1, 'Anlage 1')} · ${source(links.bri, 'Richtlinien, S. 78–81 und 105')}</p>`)}
  ${disclosure('Die Häufigkeitsberechnung in Modul 5', `<p>Es zählt die notwendige Hilfe anderer Personen bei ärztlich angeordneten Maßnahmen. Selbstständig durchgeführte Maßnahmen erzeugen keine Häufigkeitspunkte. Die Kriterien 5.1–5.7 und 5.8–5.11 bilden je eine Gruppe. Tagesdurchschnitt = pro Tag + pro Woche ÷ 7 + pro Monat ÷ 30; nach Richtlinie wird in diesen Rechenschritten auf vier Nachkommastellen gerundet.</p><ul><li>5.1–5.7: unter 1 täglich → 0; 1 bis 3 → 1; über 3 bis 8 → 2; über 8 → 3 Punkte.</li><li>5.8–5.11: seltener als wöchentlich → 0; mindestens wöchentlich, unter täglich → 1; 1 bis unter 3 täglich → 2; mindestens 3 täglich → 3 Punkte.</li><li>5.12–5.15: besondere Monatsfaktoren. 5.12 und 5.15: Woche × 8,6 / Monat × 2. 5.13 und 5.14: Woche × 4,3 / Monat × 1. Tägliche zeit- und technikintensive Maßnahmen in 5.12 erhalten 60 Zwischenpunkte.</li><li>Diese Zwischensumme wird bei 4,3 / 8,6 / 12,9 / 60 in 0 / 1 / 2 / 3 / 6 Gruppenpunkte überführt.</li><li>5.16 ergänzt 0 bis 3 Punkte für das Einhalten von Diät- oder Verhaltensvorgaben. Zusammen maximal 15 Rohpunkte.</li></ul><p>Besuche über drei Stunden einschließlich Fahrt und notwendiger Begleitung gehören zu 5.15. Derselbe Besuch wird nicht zusätzlich bei 5.13 oder 5.14 eingetragen. ${source(links.a1, 'Anlage 1')} · ${source(links.bri, 'Richtlinien, S. 82–89 und 108–110')}</p>`)}

  <h2>Von Punkten zum Pflegegrad</h2><div class="table-wrap"><table><caption>Geltende Grenzen nach § 15 Abs. 3 SGB XI</caption><thead><tr><th scope="col">Gesamtpunkte</th><th scope="col">Rechnerisches Ergebnis</th></tr></thead><tbody><tr><td>Unter 12,5</td><td>Kein Pflegegrad nach Punkten</td></tr><tr><td>12,5 bis unter 27</td><td>Pflegegrad 1</td></tr><tr><td>27 bis unter 47,5</td><td>Pflegegrad 2</td></tr><tr><td>47,5 bis unter 70</td><td>Pflegegrad 3</td></tr><tr><td>70 bis unter 90</td><td>Pflegegrad 4</td></tr><tr><td>90 bis 100</td><td>Pflegegrad 5</td></tr></tbody></table></div>
  <h3>Was bedeutet ein Punktebereich?</h3><p>Bei unsicheren oder fehlenden Antworten berechnen wir eine Unter- und Obergrenze aus den zulässigen Bewertungen. Bekannte Antworten bleiben dabei erhalten. Der Bereich beschreibt die rechnerisch offenen Möglichkeiten, keine statistische Sicherheit. Auch wenn beide Grenzen denselben Pflegegrad ergeben, bleiben die offenen Angaben sichtbar.</p>
  <h3>Grenzen des Selbstchecks</h3><p>Eine pflegefachliche Beurteilung einzelner Kriterien lässt sich nicht durch eine Website ersetzen. Der Rechner entscheidet nicht über Versicherungszeiten oder Leistungsansprüche. Kinder werden nicht mit den Erwachsenenregeln berechnet. Eine besondere Bedarfskonstellation kann Pflegegrad 5 auch unter 90 Punkten begründen; darüber entscheidet die fachliche Begutachtung.</p>
  <p>Fragen, Punktwerte, Umrechnungstabellen und Grenzen liegen getrennt von der Oberfläche in versionierten Regeldaten. Automatisierte Tests prüfen die Grenzen, Tabellen und Sonderregeln. Das schützt vor Rechenfehlern, ersetzt aber nicht die fachliche Prüfung Ihrer Angaben.</p>
  <h2>Weitere Quellen</h2><ul class="source-list"><li>${source('https://www.gesetze-im-internet.de/sgb_11/__33.html', '§ 33 SGB XI: Antrag und Leistungsvoraussetzungen')}</li><li>${source('https://www.gesetze-im-internet.de/sgb_11/__18c.html', '§ 18c SGB XI: Entscheidung und Fristen')}</li><li>${source('https://www.gesetze-im-internet.de/sgg/__84.html', '§ 84 SGG: Widerspruchsfrist')}</li><li>${source('https://www.gesetze-im-internet.de/sgg/__66.html', '§ 66 SGG: Rechtsbehelfsbelehrung')}</li><li>${source('https://www.gesetze-im-internet.de/sgg/__87.html', '§ 87 SGG: Klagefrist')}</li><li>${source(links.draft, 'PNOG-Entwurf, BT-Drs. 21/8869 vom 02.11.2026')}</li></ul><p><a class="text-link" href="#/reform">Geltendes Recht und Reformpläne auseinanderhalten →</a></p></div>`;
}

export function reformPage() {
  return `${header('Pflegereform 2027', 'Was gilt.<br>Und was geplant ist.', 'Eine klare Trennung zwischen heutigen Regeln und dem noch offenen Gesetzgebungsverfahren. Stand: 11. November 2026.')}
  <div class="prose"><div class="note"><p class="eyebrow">Gesetzentwurf · noch nicht geltend</p><h2>Der Rechner verwendet die geltenden Regeln.</h2><p>Das Pflegeneuordnungsgesetz (PNOG) ist noch nicht abschließend beschlossen und verkündet. Geplante Änderungen beeinflussen Ihr Ergebnis hier nicht.</p></div>
  <h2>Wo steht das Verfahren?</h2><ol class="steps"><li>30. September 2026: Das Bundeskabinett beschließt den Regierungsentwurf.</li><li>2. November 2026: Der Regierungsentwurf liegt als Bundestagsdrucksache 21/8869 vor.</li><li>5. November 2026: Erste Lesung im Bundestag, anschließend Überweisung an die Ausschüsse. Federführend ist der Gesundheitsausschuss.</li><li>25. November 2026: Eine Sachverständigenanhörung ist angekündigt; zum Recherchestand liegt dieser Termin in der Zukunft.</li></ol>
  <p>In der ersten Lesung wurden weitere Änderungen ausdrücklich angekündigt. Ein Kabinettsbeschluss über einen Entwurf macht dessen Regeln noch nicht verbindlich. ${source(links.debate, 'Bundestag: erste Lesung')} · ${source(links.hearing, 'Bundestag: geplante Anhörung')}</p>
  <h2>Geplante Pflegegradgrenzen</h2><p>Der Regierungsentwurf sieht höhere Einstiegsschwellen für die Pflegegrade 1 bis 3 vor. Die folgenden Zahlen sind <strong>Entwurfswerte</strong>.</p>
  <div class="table-wrap"><table><caption>Untere Punktgrenze – geltendes Recht und Regierungsentwurf</caption><thead><tr><th scope="col">Pflegegrad</th><th scope="col">Heute geltend</th><th scope="col">PNOG-Entwurf</th></tr></thead><tbody><tr><th scope="row">1</th><td>12,5</td><td>15</td></tr><tr><th scope="row">2</th><td>27</td><td>30</td></tr><tr><th scope="row">3</th><td>47,5</td><td>50</td></tr><tr><th scope="row">4</th><td>70</td><td>70</td></tr><tr><th scope="row">5</th><td>90</td><td>90</td></tr></tbody></table></div>
  <p>Quelle: ${source(links.sgb15, 'geltender § 15 SGB XI')} und ${source(links.draft, 'Entwurf, S. 28')}.</p>
  <h3>Auch die Umrechnung soll sich ändern.</h3><p>Die gleichen Antworten könnten künftig zu einer anderen Gesamtpunktzahl führen. Der Entwurf ändert Rohpunktbereiche in Mobilität, Selbstversorgung und Alltagsgestaltung. Deshalb wäre es irreführend, Ihr heutiges Ergebnis lediglich mit den geplanten Gesamtgrenzen zu vergleichen.</p>
  ${disclosure('Welche Rohpunktbereiche sind im Entwurf vorgesehen?', `<div class="table-wrap"><table><caption>Entwurf der Anlage 2 – fünf Stufen, von keiner bis schwerster Beeinträchtigung</caption><thead><tr><th scope="col">Modul</th><th scope="col">Geplante Rohpunktbereiche</th></tr></thead><tbody><tr><th scope="row">1 · Mobilität</th><td>0–1 / 2–3 / 4–6 / 7–9 / 10–15</td></tr><tr><th scope="row">2 · Kognition</th><td>0–1 / 2–5 / 6–10 / 11–16 / 17–33</td></tr><tr><th scope="row">3 · Verhalten</th><td>0 / 1–2 / 3–4 / 5–6 / 7–65</td></tr><tr><th scope="row">4 · Selbstversorgung</th><td>0–3 / 4–9 / 10–24 / 25–39 / 40–54</td></tr><tr><th scope="row">5 · Krankheiten & Therapien</th><td>0 / 1 / 2–3 / 4–5 / 6–15</td></tr><tr><th scope="row">6 · Alltag & Kontakte</th><td>0–1 / 2–3 / 4–6 / 7–11 / 12–18</td></tr></tbody></table></div><p>Die gewichteten Stufen bleiben im Entwurf gleich. ${source(links.draft, 'BT-Drs. 21/8869, S. 54')} · <a href="#/quellen">Geltende Tabelle ansehen</a></p>`)}
  <h2>Was soll für bestehende Anträge gelten?</h2><p>Der geplante § 142b knüpft grundsätzlich an das Recht zum Zeitpunkt des Antrags an. Bei Wiederholungsbegutachtungen soll der Begutachtungstag maßgeblich sein. Eine bestehende Einstufung soll nicht allein wegen geänderter Schwellen oder Tabellen verloren gehen. Das ist geplanter Schutz des Pflegegrades, keine Garantie unveränderter einzelner Leistungen.</p>
  <p>Für Januar bis April 2027 sieht der Entwurf außerdem eine Ausnahme von der regulären Entscheidungsfrist vor, mit Sonderregeln für besonders dringliche Fälle. <strong>Diese Ausnahme gilt heute nicht.</strong> ${source(links.draft, 'Entwurf, § 142b, S. 52–53')}</p>
  <h3>Und bei einem Widerspruch?</h3><p>Eine neue besondere Widerspruchsfrist ist in den hier geprüften Regelungen nicht belegt. Die geplante Anknüpfung an das Antragsdatum könnte bei fortgeführten Verfahren für den Bewertungsstand wichtig sein. Verbindlich lässt sich das erst anhand des endgültigen Gesetzes und des Einzelfalls beurteilen. Bis dahin bleiben die <a href="#/ratgeber">geltenden Widerspruchsregeln</a> maßgeblich.</p>
  <h2>Entlastungsleistungen und Pflegebudgets</h2><p><strong>Heute:</strong> Bei häuslicher Pflege besteht ein zweckgebundener Entlastungsbetrag von bis zu 131 Euro monatlich, auch in Pflegegrad 1. ${source('https://www.gesetze-im-internet.de/sgb_11/__45b.html', '§ 45b SGB XI')}</p>
  <p><strong>Geplant:</strong> Leistungen sollen in Sachleistungs-, Entlastungs- und Überbrückungsbudgets neu geordnet werden. Ein Sozialraumbudget soll in Pflegegrad 2 bis 5 an die Stelle des bisherigen Entlastungsbetrags treten: bis zu 175 Euro monatlich, für unter 25-Jährige bis zu 300 Euro, jeweils für anerkannte Alltagsangebote. Pflegegrad 1 soll darauf keinen Zugriff haben; vorgesehen sind verstärkte Beratung und später Pflegebegleitung. ${source(links.reform, 'BMG: Fragen zum Entwurf')}</p>
  <p>Gerade diese Leistungsänderungen werden parlamentarisch diskutiert. Die geplanten Beträge und Starttermine können sich noch ändern. Diese Website bietet daher keinen verbindlichen Reformvergleich und leitet daraus keine Antragsempfehlung für einen bestimmten Stichtag ab.</p>
  <p class="note">Das Hauptinkrafttreten ist im Entwurf für den 1. Januar 2027 geplant, einzelne Regelungen später. Ein geplanter Termin ist kein bereits beschlossenes Inkrafttreten. ${source(links.draft, 'Artikel 11 des Entwurfs, S. 61')}</p>
  <a class="text-link" href="#/rechner">Selbstcheck nach geltendem Recht starten →</a></div>`;
}

export function privacyPage() {
  return `${header('Datenschutz', 'Ihre Antworten.<br>Auf Ihrem Gerät.', 'Der Selbstcheck ist so gestaltet, dass Sie keine persönlichen Kontaktdaten angeben müssen und Ihre Gesundheitsantworten im Browser bleiben.')}
  <div class="prose"><h2>So arbeitet der Rechner</h2><ul><li>Keine Anmeldung und keine Abfrage von Namen, Anschrift oder Kontaktdaten.</li><li>Die Berechnung findet auf Ihrem Gerät statt. Antworten und Ergebnisse werden nicht an einen Server, KI-Dienst oder Analysedienst übermittelt.</li><li>Der Rechner verwendet für Ihre Antworten keine Cookies und keinen dauerhaften Browserspeicher.</li><li>Zurücksetzen oder Neuladen verwirft den aktuellen Antwortstand.</li><li>Ein PDF wird auf Ihrem Gerät erstellt. Heruntergeladene Dateien und Ausdrucke verwalten Sie selbst.</li><li>Die Website enthält keine Werbe- oder Tracking-Skripte. Gesundheitsantworten werden nicht verkauft oder werblich genutzt.</li></ul>
  <h2>Aufruf der Website und externe Links</h2><p>Die private Projektvorschau kann einen Zugang über die Hostingplattform verlangen. Der Selbstcheck selbst besitzt kein Benutzerkonto. Die Zugangsprüfung der Plattform und deren technische Datenverarbeitung sind von Ihren lokal verarbeiteten Gesundheitsantworten zu unterscheiden.</p><p>Beim Abruf einer gehosteten Website fallen technische Verbindungsdaten an, zum Beispiel die IP-Adresse. Diese sind von den Gesundheitsantworten zu unterscheiden. Die genaue Verarbeitung hängt von der tatsächlich eingesetzten Hostingumgebung ab.</p><p>Amtliche Quellen öffnen erst nach Ihrer Auswahl als externe Seiten. Dort gelten die Datenschutzhinweise des jeweiligen Anbieters. Der Inhalt Ihres Selbstchecks wird nicht an diese Links angehängt.</p>
  <h2>Besonders schützenswerte Angaben</h2><p>Personenbezogene Gesundheitsdaten unterliegen Art. 9 DSGVO. Die lokale, datenarme Gestaltung vermeidet ihre Übertragung an den Betreiber. Füllen Sie einen Check für eine andere Person nur unter Wahrung ihres Einverständnisses und ihrer Privatsphäre aus. Teilen oder versenden Sie einen Ergebnisbericht nur bewusst.</p>
  <div class="note"><p class="eyebrow">Private Projektvorschau</p><h2>Hinweise zur Veröffentlichung</h2><p>Diese Vorschau ist noch keine vollständig ausgefüllte Datenschutzerklärung für den öffentlichen Betrieb. Der rechtliche Betreiber, seine Kontaktadresse und die verbindlichen Hostingangaben wurden noch nicht mitgeteilt.</p><p>Vor einer öffentlichen Freigabe müssen Verantwortlicher, Rechtsgrundlagen, technische Empfänger, Speicherfristen, etwaige Drittlandübermittlungen und die zuständige Aufsichtsbehörde ergänzt und geprüft werden. Diese Angaben werden nicht erfunden.</p></div>
  <h2>Ihre Datenschutzrechte</h2><p>Soweit ein Betreiber personenbezogene Daten verarbeitet, bestehen nach den gesetzlichen Voraussetzungen insbesondere Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch sowie auf Beschwerde bei einer Datenschutzaufsichtsbehörde. Eine Einwilligung kann für die Zukunft widerrufen werden. Für den öffentlichen Betrieb sind die zuständigen Kontaktstellen konkret zu benennen.</p>
  <ul class="source-list"><li>${source('https://www.datenschutz.sachsen.de/informationspflichten.html', 'Datenschutzaufsicht: Informationspflichten nach Art. 13 DSGVO')}</li><li>${source('https://www.gesetze-im-internet.de/ttdsg/__25.html', '§ 25 TDDDG: Schutz von Endgeräten')}</li><li>${source('https://www.bfdi.bund.de/SharedDocs/Downloads/DE/DSK/DSKEntschliessungen/98DSK_GesundheitswebseitenGesundheitsApps.pdf?__blob=publicationFile&v=7', 'Datenschutzkonferenz: Gesundheitswebsites und Gesundheits-Apps')}</li></ul><p>Stand dieser technischen Hinweise: 11. November 2026.</p></div>`;
}

export function imprintPage() {
  return `${header('Impressum', 'Ein klarer Absender.<br>Ein transparenter Stand.', 'Diese Website ist als kostenloser Informationsservice von Caro Alltagsbegleitung in Tübingen vorgesehen.')}
  <div class="prose"><div class="note"><p class="eyebrow">Private Projektvorschau</p><h2>Betreiberangaben noch zu ergänzen</h2><p>Die für ein vollständiges Impressum erforderlichen Angaben liegen für diese Vorschau noch nicht vor. Vor einer öffentlichen Veröffentlichung müssen der rechtliche Betreibername, die Rechtsform, die ladungsfähige Anschrift, die E-Mail-Adresse und gegebenenfalls Vertretungs- und Registerangaben verbindlich ergänzt werden.</p><p>„Caro Alltagsbegleitung, Tübingen“ ersetzt diese Pflichtangaben nicht. ${source('https://www.gesetze-im-internet.de/ddg/__5.html', '§ 5 DDG')}</p></div>
  <h2>Einordnung des Angebots</h2><p>Caro ist weder Pflegeversicherung noch Medizinischer Dienst oder staatliche Behörde. Die Website informiert über das Verfahren und bietet eine unverbindliche Selbsteinschätzung. Sie stellt keine Pflegegrade fest und verspricht keine Bewilligung.</p><p>Der tatsächliche Pflegegrad wird durch die zuständige Pflegeversicherung auf Grundlage der Begutachtung festgestellt. Das Ergebnis kann von diesem Rechner abweichen.</p><h2>Redaktioneller und rechtlicher Stand</h2><p>Die Grundlagen wurden am 11. November 2026 anhand offizieller Quellen recherchiert. Sie finden die verwendeten Normen und die geltenden Richtlinien unter <a href="#/quellen">Quellen & Methodik</a>. Reformpläne stehen gesondert unter <a href="#/reform">Pflegereform 2027</a>.</p><p>Für Auskünfte zu einem eigenen Antrag wenden Sie sich an Ihre Pflegeversicherung oder eine unabhängige Pflegeberatung. Diese Vorschau enthält bewusst keine ungeprüften Kontaktadressen.</p></div>`;
}
